import json
import re
from system_tools import call_llm

def solve_numerical_problem_agentic(question: str) -> str:
    """
    An LLM-driven agentic approach to solve numerical problems.
    Uses chain-of-thought, extraction, calculation, and verification steps.
    """
    max_retries = 2

    # Step 1: LLM for Initial Understanding and Plan
    system_instruction_plan = "You are a problem-solving agent. Analyze the user's question, identify the core task, and outline a step-by-step plan to solve it."
    plan_prompt = f"""
    Analyze the following question and provide a structured plan to solve it.
    The plan should include steps for:
    1. Extracting relevant numerical data and operations.
    2. Performing the necessary calculations.
    3. Verifying the final answer.

    Example Question: "If a box contains 10 red apples and 5 green apples, how many apples are there in total?"
    Example Plan:
    {{
      "task": "Calculate total number of apples.",
      "steps": [
        "Identify numerical values for red and green apples.",
        "Determine the required operation (addition for total).",
        "Perform the addition.",
        "Verify the sum."
      ]
    }}

    Question: "{question}"
    Plan:
    """

    plan_response = call_llm(plan_prompt, system_instruction_plan)
    try:
        plan = json.loads(plan_response)
        if not all(k in plan for k in ["task", "steps"]):
            raise ValueError("Invalid plan structure")
    except (json.JSONDecodeError, ValueError):
        print("LLM failed to provide a valid plan. Falling back to default plan.")
        plan = {
            "task": "Solve numerical problem",
            "steps": [
                "Extract numerical values and explicit operations.",
                "Perform calculation.",
                "Verify the result."
            ]
        }

    # Step 2: LLM for Data Extraction (first step of the plan)
    extracted_data = None
    for attempt in range(max_retries):
        system_instruction_extract = "You are a data extraction expert. Identify all numerical values and explicit mathematical operations needed from the user's question. Return as JSON."
        extract_prompt = f"""
        Extract numerical values and the primary mathematical operation(s) from the following question.

        Example Question: "If there are 10 apples and you add 5 more, what is the total?"
        Example Output:
        {{
          "numbers": [10, 5],
          "operation": "add"
        }}

        Example Question: "What is 20 minus 7?"
        Example Output:
        {{
          "numbers": [20, 7],
          "operation": "subtract"
        }}

        Question: "{question}"
        Output:
        """
        extract_response = call_llm(extract_prompt, system_instruction_extract)
        try:
            extracted_data = json.loads(extract_response)
            if all(k in extracted_data for k in ["numbers", "operation"]):
                break
            else:
                raise ValueError("Incomplete extraction")
        except (json.JSONDecodeError, ValueError) as e:
            print(f"Extraction failed (attempt {attempt+1}): {e}. Retrying...")
            if attempt == max_retries - 1:
                return "Could not extract necessary information."

    # Step 3: Python for Calculation (based on extracted data)
    final_answer = None
    if extracted_data:
        numbers = extracted_data.get("numbers", [])
        operation = extracted_data.get("operation")

        try:
            if operation == "add" and len(numbers) >= 2:
                final_answer = sum(numbers)
            elif operation == "subtract" and len(numbers) >= 2:
                final_answer = numbers[0] - numbers[1]
            # Add more operations as needed
            else:
                return f"Unsupported operation or insufficient numbers for operation '{operation}'."
        except Exception as e:
            return f"Error during calculation: {e}"

    if final_answer is None:
        return "Calculation could not be performed."

    # Step 4: LLM for Verification (last step of the plan)
    for attempt in range(max_retries):
        system_instruction_verify = "You are a verification agent. Double-check if the provided answer correctly solves the original question. Return a JSON with verification status and explanation."
        verify_prompt = f"""
        Verify if the following answer correctly solves the original question.

        Original Question: "{question}"
        Proposed Answer: "{final_answer}"

        Example Original Question: "What is 5 plus 3?"
        Example Proposed Answer: "8"
        Example Output:
        {{
          "is_correct": true,
          "explanation": "5 + 3 is indeed 8."
        }}

        Example Original Question: "What is 10 minus 2?"
        Example Proposed Answer: "5"
        Example Output:
        {{
          "is_correct": false,
          "explanation": "10 - 2 is 8, not 5. The proposed answer is incorrect."
        }}

        Output:
        """
        verify_response = call_llm(verify_prompt, system_instruction_verify)
        try:
            verification_result = json.loads(verify_response)
            if verification_result.get("is_correct"):
                return str(final_answer)
            else:
                print(f"Verification failed: {verification_result.get('explanation', 'No explanation provided.')}. Retrying calculation...")
                # If verification fails, we could potentially re-extract or re-calculate
                # For simplicity, this example just returns the error after max_retries
                break
        except json.JSONDecodeError as e:
            print(f"Verification response parsing failed (attempt {attempt+1}): {e}. Retrying...")
            if attempt == max_retries - 1:
                return "Could not verify the answer due to parsing issues."

    return str(final_answer) # Return the answer even if verification had issues after retries

def main(question: str) -> str:
    """
    Main entry point for the validation script.
    Takes a question string and returns the answer.
    """
    return solve_numerical_problem_agentic(question)

if __name__ == "__main__":
    # Test cases
    test_questions = [
        "What is 10 plus 5?",
        "If a person has 25 apples and gives away 10, how many are left?",
        "Calculate the sum of 100 and 200.",
        "What is two plus two?" # LLM might struggle with non-digit numbers without more context/prompt engineering
    ]

    for q in test_questions:
        print(f"\nSolving: {q}")
        answer = solve_numerical_problem_agentic(q)
        print(f"Answer: {answer}")
